package com.bank.logmerge.service;

import java.util.logging.Logger;

// Shortest common supersequence length = m + n - longest common subsequence.
public class LogMergeService {
    private static final Logger log = Logger.getLogger(LogMergeService.class.getName());

    public int shortestMergedLength(String a, String b) {
        int m = a.length(), n = b.length();
        int[][] dp = new int[m + 1][n + 1];         // longest common subsequence table
        for (int i = 1; i <= m; i++) {
            for (int j = 1; j <= n; j++) {
                if (a.charAt(i - 1) == b.charAt(j - 1))
                    dp[i][j] = 1 + dp[i - 1][j - 1];
                else
                    dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }
        int lcs = dp[m][n];
        final int r = m + n - lcs;                  // shared part written once
        log.info(() -> "Shortest merged log length = " + r);
        return r;
    }
}
